function LPF_Analyze
% LPF_ANALYZE Characterize the fully differential LPF and SEL testbench.
%
% The formal report covers 45 PVT corners. The selector transient is a
% nominal functional check only. Monte Carlo reporting uses the MM, GL,
% and FULL summary files generated by the LPF statistical testbenches.

clc;
close all;

scriptDir = fileparts(mfilename('fullpath'));
plotDir = fullfile(scriptDir,'Plots');
reportDir = fullfile(scriptDir,'Reports');
if ~isfolder(plotDir), mkdir(plotDir); end
if ~isfolder(reportDir), mkdir(reportDir); end

cfg = analysisConfig();
rows = reportRows();

processes = ["NOM" "FF" "SS" "FS" "SF"];
processTokens = lower(processes);
cases = ["nom" "vl" "vh" "tl" "th" "vltl" "vlth" "vhtl" "vhth"];
caseLabels = ["NOMNOM" "VLNOM" "VHNOM" "NOMTL" "NOMTH" ...
    "VLTL" "VLTH" "VHTL" "VHTH"];
caseVdd_V = [3.3 3.0 3.6 3.3 3.3 3.0 3.0 3.6 3.6];
caseTemp_C = [27 27 27 -40 125 -40 125 -40 125];

nCorners = numel(processes)*numel(cases);
corners = strings(1,nCorners);
cornerProcesses = strings(1,nCorners);
cornerCases = strings(1,nCorners);
cornerVdd_V = nan(1,nCorners);
cornerTemp_C = nan(1,nCorners);
values = nan(size(rows,1),nCorners);
valueRelations = strings(size(rows,1),nCorners);
metrics = cell(1,nCorners);

cornerIndex = 0;
for processIndex = 1:numel(processes)
    process = processes(processIndex);
    processToken = processTokens(processIndex);
    resultDir = fullfile(scriptDir,processToken+".Result_txt");
    for caseIndex = 1:numel(cases)
        cornerIndex = cornerIndex+1;
        caseToken = cases(caseIndex);
        corners(cornerIndex) = process+caseLabels(caseIndex);
        cornerProcesses(cornerIndex) = process;
        cornerCases(cornerIndex) = caseLabels(caseIndex);
        cornerVdd_V(cornerIndex) = caseVdd_V(caseIndex);
        cornerTemp_C(cornerIndex) = caseTemp_C(caseIndex);
        metrics{cornerIndex} = analyzeRun(resultDir,processToken,caseToken, ...
            caseVdd_V(caseIndex),cfg);
        values(:,cornerIndex) = metricsToRaw(metrics{cornerIndex}, ...
            rows,caseTemp_C(caseIndex),cfg.targetGain_VV);
        valueRelations(:,cornerIndex) = metricsToRelations( ...
            metrics{cornerIndex},rows);
    end
end

specifications = specStrings(rows(:,1));
checkReportSpecCoverage(rows,specifications);
checkPvtSpecifications(rows,values,corners);

nominalCorner = parameterIndex(corners,"NOMNOMNOM");
reportColumns = ["NOM" "FF" "SS" "FS" "SF" "VL" "VH" "TL" "TH"];
reportKeys = ["NOMNOMNOM" "FFNOMNOM" "SSNOMNOM" "FSNOMNOM" ...
    "SFNOMNOM" "NOMVLNOM" "NOMVHNOM" "NOMNOMTL" "NOMNOMTH"];
[found,reportIndices] = ismember(reportKeys,corners);
if ~all(found)
    error('LPF_Analyze:ReportCorners', ...
        'One or more required comparison corners are missing.');
end

formattedValues = formatReportValues(rows,values,valueRelations);
reportValues = formattedValues(:,reportIndices);
summaryTable = table(rows(:,1),rows(:,2),specifications, ...
    'VariableNames',{'Parameter','Unit','Spec'});
summaryTable = [summaryTable array2table(reportValues, ...
    'VariableNames',cellstr(reportColumns))];
fprintf('\nLPF COMPARISON SUMMARY\n\n');
printSummaryTable(rows,specifications,reportColumns,reportValues);
writetable(summaryTable,fullfile(reportDir,'LPF_table_report.csv'));
writetable(summaryTable,fullfile(reportDir,'NOM.LPF_summary.csv'));

fullPvtTable = buildFullPvtTable(rows,values,corners,cornerProcesses, ...
    cornerCases,cornerVdd_V,cornerTemp_C,valueRelations);
writetable(fullPvtTable,fullfile(reportDir,'LPF_full_pvt_report.csv'));

worstCase = buildWorstCaseTable(rows,values,corners,valueRelations);
fprintf('\nLPF FULL-PVT WORST CASE\n\n');
printWorstCaseTable(worstCase);
writetable(worstCase,fullfile(reportDir,'LPF_worst_case_report.csv'));

plotNominalFrequencyResponse(metrics{nominalCorner},plotDir,cfg);
plotNominalVtc(metrics{nominalCorner},plotDir,cfg);
plotNominalCmrr(metrics{nominalCorner},plotDir,cfg);
plotNominalNoise(metrics{nominalCorner},plotDir,cfg);
plotSelectorTransient(scriptDir,plotDir);
runMcSection(scriptDir,plotDir,reportDir,cfg);
end

function cfg = analysisConfig
cfg.targetGain_VV = 1;
cfg.referenceFrequency_Hz = 10;
cfg.band_Hz = [0.05 150];
cfg.rejectionFrequencies_Hz = [60 150];
cfg.vtcCompression_pct = 1;
cfg.vtcCenterFitHalfWidth_V = 0.1;
cfg.thdFrequency_Hz = 60;
cfg.mcRequestedRuns = 200;
end

function rows = reportRows
rows = [
    "Set conditions",                         ""
    "AVDD",                                   "V"
    "Temperature",                            "C"
    "LPF target gain",                        "V/V"
    "",                                       ""
    "Operating point",                        ""
    "FDC bias current",                       "uA"
    "CMFB bias current",                      "uA"
    "Total current",                          "mA"
    "Total power",                            "mW"
    "Output CM error",                        "mV"
    "LPF input offset",                       "mV"
    "",                                       ""
    "LPF",                                    ""
    "Passband gain",                          "V/V"
    "Passband gain error",                    "%"
    "Loss @ 150 Hz",                          "dB"
    "LPF -1 dB frequency",                    "Hz"
    "LPF -3 dB frequency",                    "Hz"
    "Input range low",                        "V"
    "Input range high",                       "V"
    "Output range low",                       "V"
    "Output range high",                      "V"
    "CMRR @ 60 Hz",                           "dB"
    "CMRR @ 150 Hz",                          "dB"
    "PSRR+ @ 60 Hz",                          "dB"
    "PSRR+ @ 150 Hz",                         "dB"
    "PSRR- @ 60 Hz",                          "dB"
    "PSRR- @ 150 Hz",                         "dB"
    "Input-referred noise 0.05-150 Hz",       "uVrms"
    "THD @ 60 Hz, 1.2 Vpp",                   "%"
];
end

function specifications = specStrings(parameters)
specifications = strings(size(parameters));
for index = 1:numel(parameters)
    specifications(index) = specText(parameters(index));
end
end

function specification = specText(parameter)
switch string(parameter)
    case {"FDC bias current","CMFB bias current"}
        specification = "40±10";
    case "Total current"
        specification = "≤2.5";
    case "Total power"
        specification = "≤9";
    case "Output CM error"
        specification = "±25";
    case "LPF input offset"
        specification = "±6";
    case "Passband gain error"
        specification = "±0.5";
    case "LPF -1 dB frequency"
        specification = "≥150";
    case {"Input range low","Output range low"}
        specification = "≤-1.2";
    case {"Input range high","Output range high"}
        specification = "≥1.2";
    case {"CMRR @ 60 Hz","CMRR @ 150 Hz", ...
            "PSRR+ @ 60 Hz","PSRR+ @ 150 Hz", ...
            "PSRR- @ 60 Hz","PSRR- @ 150 Hz"}
        specification = "≥80";
    case "Input-referred noise 0.05-150 Hz"
        specification = "≤10";
    case "THD @ 60 Hz, 1.2 Vpp"
        specification = "≤0.05";
    otherwise
        specification = "";
end
end

function checkReportSpecCoverage(rows,specifications)
descriptive = ["Set conditions" "AVDD" "Temperature" "LPF target gain" ...
    "Operating point" "LPF" "Passband gain" ...
    "Loss @ 150 Hz" ...
    "LPF -3 dB frequency"];
missing = rows(:,2) ~= "" & strlength(specifications) == 0 & ...
    ~ismember(rows(:,1),descriptive);
if any(missing)
    error('LPF_Analyze:MissingReportSpec', ...
        'Formal report row(s) have no specification: %s', ...
        strjoin(rows(missing,1),', '));
end
end

function pass = specPass(parameter,value)
if ~isfinite(value)
    pass = false;
    return;
end
switch string(parameter)
    case {"FDC bias current","CMFB bias current"}
        pass = value >= 30 && value <= 50;
    case "Total current"
        pass = value <= 2.5;
    case "Total power"
        pass = value <= 9;
    case "Output CM error"
        pass = abs(value) <= 25;
    case "LPF input offset"
        pass = abs(value) <= 6;
    case "Passband gain error"
        pass = abs(value) <= 0.5;
    case "LPF -1 dB frequency"
        pass = value >= 150;
    case {"Input range low","Output range low"}
        pass = value <= -1.2;
    case {"Input range high","Output range high"}
        pass = value >= 1.2;
    case {"CMRR @ 60 Hz","CMRR @ 150 Hz", ...
            "PSRR+ @ 60 Hz","PSRR+ @ 150 Hz", ...
            "PSRR- @ 60 Hz","PSRR- @ 150 Hz"}
        pass = value >= 80;
    case "Input-referred noise 0.05-150 Hz"
        pass = value <= 10;
    case "THD @ 60 Hz, 1.2 Vpp"
        pass = value <= 0.05;
    otherwise
        pass = true;
end
end

function checkPvtSpecifications(rows,values,corners)
required = strlength(specStrings(rows(:,1))) > 0;
failures = strings(0,1);
passedCorners = 0;
for cornerIndex = 1:numel(corners)
    cornerPass = true;
    for rowIndex = find(required)'
        if ~specPass(rows(rowIndex,1),values(rowIndex,cornerIndex))
            cornerPass = false;
            failures(end+1) = sprintf('%s: %s=%s %s',corners(cornerIndex), ...
                rows(rowIndex,1),formatOne(values(rowIndex,cornerIndex), ...
                rows(rowIndex,2)),rows(rowIndex,2)); %#ok<AGROW>
        end
    end
    passedCorners = passedCorners+cornerPass;
end
if isempty(failures)
    fprintf('\nLPF FULL-PVT VERIFICATION: PASS (%d/%d corners)\n', ...
        passedCorners,numel(corners));
else
    warning('LPF_Analyze:PvtSpecFailure', ...
        'LPF FULL-PVT VERIFICATION: FAIL (%d/%d corners):\n%s', ...
        passedCorners,numel(corners),strjoin(failures,newline));
end
end

function m = analyzeRun(resultDir,processToken,caseToken,expectedVdd_V,cfg)
files = runFiles(resultDir,processToken,caseToken);
m.vos_V = readScalar(files.vos);
op = readNumericFile(files.op,14);
op = op(end,:);
m.vdd_V = op(2);
m.outputCmError_V = op(8);
m.totalCurrent_A = op(11);
m.totalPower_W = op(12);
m.fdcBias_A = op(13);
m.cmfbBias_A = op(14);
if abs(m.vdd_V-expectedVdd_V) > 1e-6
    error('LPF_Analyze:SupplyMismatch', ...
        '%s reports AVDD %.9g V; expected %.9g V.', ...
        files.op,m.vdd_V,expectedVdd_V);
end

m.diff = analyzeDifferential(readNumericFile(files.diff,7),cfg);
m.rejection = analyzeRejection( ...
    readNumericFile(files.cmrr,5), ...
    readNumericFile(files.psrrP,5), ...
    readNumericFile(files.psrrN,5),m.diff,cfg);
m.noise = analyzeNoise(readNumericFile(files.noise,3),cfg);
m.vtc = analyzeVtc(readNumericFile(files.vtc,6),cfg);
m.thd = analyzeThd(readNumericFile(files.thd,3),cfg.thdFrequency_Hz);
end

function files = runFiles(resultDir,processToken,caseToken)
stem = processToken+".%s_"+caseToken+".txt";
files.vos = fullfile(resultDir,sprintf(stem,'vos'));
files.op = fullfile(resultDir,sprintf(stem,'op'));
files.diff = fullfile(resultDir,sprintf(stem,'diff_ac'));
files.cmrr = fullfile(resultDir,sprintf(stem,'cmrr_ac'));
files.psrrP = fullfile(resultDir,sprintf(stem,'psrrp_ac'));
files.psrrN = fullfile(resultDir,sprintf(stem,'psrrn_ac'));
files.noise = fullfile(resultDir,sprintf(stem,'noise'));
files.vtc = fullfile(resultDir,sprintf(stem,'vtc'));
files.thd = fullfile(resultDir,sprintf(stem,'thd'));
end

function result = analyzeDifferential(data,cfg)
f = data(:,1);
validateFrequency(f,'differential AC');
vin = complex(data(:,2),data(:,3));
vout = complex(data(:,4),data(:,5));
if any(abs(vin) == 0)
    error('LPF_Analyze:ZeroDifferentialInput', ...
        'Differential AC input contains a zero magnitude.');
end
gain = abs(vout./vin);
gain_dB = 20*log10(gain);
gain10_dB = interpLog(f,gain_dB,cfg.referenceFrequency_Hz);
gain150_dB = interpLog(f,gain_dB,cfg.band_Hz(2));
gain10_VV = 10^(gain10_dB/20);
relative_dB = gain_dB-gain10_dB;

result.frequency_Hz = f;
result.gain_VV = gain;
result.relativeGain_dB = relative_dB;
result.gain10_VV = gain10_VV;
result.gainError_pct = 100*(gain10_VV-cfg.targetGain_VV)/cfg.targetGain_VV;
result.loss150_dB = gain10_dB-gain150_dB;
result.frequency1dB_Hz = descendingCrossing(f,relative_dB,-1, ...
    cfg.referenceFrequency_Hz);
result.frequency3dB_Hz = descendingCrossing(f,relative_dB,-3, ...
    cfg.referenceFrequency_Hz);
end

function result = analyzeRejection(cmData,psrrPData,psrrNData,diff,cfg)
testF = cfg.rejectionFrequencies_Hz;
ad = interpLog(diff.frequency_Hz,diff.gain_VV,testF);
[cmFrequency_Hz,cmMagnitude] = transferMagnitudeCurve(cmData,'CMRR AC');
acm = interpLog(cmFrequency_Hz,cmMagnitude,testF);
[psrrPFrequency_Hz,psrrPMagnitude] = transferMagnitudeCurve(psrrPData,'PSRR+ AC');
[psrrNFrequency_Hz,psrrNMagnitude] = transferMagnitudeCurve(psrrNData,'PSRR- AC');
asP = interpLog(psrrPFrequency_Hz,psrrPMagnitude,testF);
asN = interpLog(psrrNFrequency_Hz,psrrNMagnitude,testF);
result.cmrr_dB = 20*log10(ad./acm);
result.cmrrFrequency_Hz = cmFrequency_Hz;
result.cmrrCurve_dB = 20*log10( ...
    interpLog(diff.frequency_Hz,diff.gain_VV,cmFrequency_Hz)./cmMagnitude);
result.psrrP_dB = 20*log10(ad./asP);
result.psrrN_dB = 20*log10(ad./asN);
result.rejectionFrequency_Hz = diff.frequency_Hz;
result.psrrPCurve_dB = 20*log10(diff.gain_VV./ ...
    interpLog(psrrPFrequency_Hz,psrrPMagnitude,diff.frequency_Hz));
result.psrrNCurve_dB = 20*log10(diff.gain_VV./ ...
    interpLog(psrrNFrequency_Hz,psrrNMagnitude,diff.frequency_Hz));
end

function [f,magnitude] = transferMagnitudeCurve(data,label)
f = data(:,1);
validateFrequency(f,label);
source = complex(data(:,2),data(:,3));
output = complex(data(:,4),data(:,5));
if any(abs(source) == 0)
    error('LPF_Analyze:ZeroAcSource','%s source contains zero magnitude.',label);
end
magnitude = abs(output./source);
end

function result = analyzeNoise(data,cfg)
f = data(:,1);
validateFrequency(f,'noise');
result.frequency_Hz = f;
result.inputDensity_VrtHz = abs(data(:,3));
result.inputRms_V = integrateDensity(f,result.inputDensity_VrtHz,cfg.band_Hz);
end

function result = analyzeVtc(data,cfg)
vinDiff_V = data(:,2);
lpfOutDiff_V = data(:,6);
if any(diff(vinDiff_V) <= 0)
    error('LPF_Analyze:VtcInput', ...
        'LPF VTC input must be strictly increasing.');
end

[~,zeroIndex] = min(abs(lpfOutDiff_V));
fitRows = abs(vinDiff_V-vinDiff_V(zeroIndex)) <= ...
    cfg.vtcCenterFitHalfWidth_V;
if nnz(fitRows) < 3
    error('LPF_Analyze:VtcFit', ...
        'LPF VTC central gain fit requires at least three samples.');
end
centralFit = polyfit(vinDiff_V(fitRows),lpfOutDiff_V(fitRows),1);
centralGain_VV = centralFit(1);
if ~isfinite(centralGain_VV) || abs(centralGain_VV) <= eps
    error('LPF_Analyze:VtcGain', ...
        'LPF VTC central DC gain must be finite and nonzero.');
end

localGain_VV = gradient(lpfOutDiff_V)./gradient(vinDiff_V);
gainError_pct = 100*abs(localGain_VV/centralGain_VV-1);

negativeInsideIndex = zeroIndex;
negativeOutsideIndex = [];
for index = zeroIndex-1:-1:1
    if isfinite(gainError_pct(index)) && ...
            gainError_pct(index) <= cfg.vtcCompression_pct
        negativeInsideIndex = index;
    else
        negativeOutsideIndex = index;
        break;
    end
end

positiveInsideIndex = zeroIndex;
positiveOutsideIndex = [];
for index = zeroIndex+1:numel(vinDiff_V)
    if isfinite(gainError_pct(index)) && ...
            gainError_pct(index) <= cfg.vtcCompression_pct
        positiveInsideIndex = index;
    else
        positiveOutsideIndex = index;
        break;
    end
end

negativeAtBoundary = isempty(negativeOutsideIndex);
positiveAtBoundary = isempty(positiveOutsideIndex);

if negativeAtBoundary
    inputNegative_V = vinDiff_V(1);
    outputNegative_V = lpfOutDiff_V(1);
else
    inputNegative_V = compressionCrossing( ...
        vinDiff_V(negativeOutsideIndex),gainError_pct(negativeOutsideIndex), ...
        vinDiff_V(negativeInsideIndex),gainError_pct(negativeInsideIndex), ...
        cfg.vtcCompression_pct);
    outputNegative_V = interp1(vinDiff_V,lpfOutDiff_V,inputNegative_V,'linear');
end

if positiveAtBoundary
    inputPositive_V = vinDiff_V(end);
    outputPositive_V = lpfOutDiff_V(end);
else
    inputPositive_V = compressionCrossing( ...
        vinDiff_V(positiveInsideIndex),gainError_pct(positiveInsideIndex), ...
        vinDiff_V(positiveOutsideIndex),gainError_pct(positiveOutsideIndex), ...
        cfg.vtcCompression_pct);
    outputPositive_V = interp1(vinDiff_V,lpfOutDiff_V,inputPositive_V,'linear');
end

result.input_V = vinDiff_V;
result.output_V = lpfOutDiff_V;
result.centralGain_VV = centralGain_VV;
result.inputNegative_V = inputNegative_V;
result.inputPositive_V = inputPositive_V;
result.outputNegative_V = outputNegative_V;
result.outputPositive_V = outputPositive_V;
result.negativeAtBoundary = negativeAtBoundary;
result.positiveAtBoundary = positiveAtBoundary;
end

function crossing = compressionCrossing(x1,error1,x2,error2,target)
if ~all(isfinite([x1 error1 x2 error2])) || error1 == error2
    crossing = x2;
    return;
end
fraction = (target-error1)/(error2-error1);
crossing = x1+fraction*(x2-x1);
end

function result = analyzeThd(data,fundamental_Hz)
t_s = data(:,1);
lpfOutDiff_V = data(:,3);
if any(diff(t_s) <= 0)
    error('LPF_Analyze:ThdTime', ...
        'THD transient time must be strictly increasing.');
end
duration_s = t_s(end)-t_s(1);
cycleCount = duration_s*fundamental_Hz;
if abs(cycleCount-round(cycleCount)) > 1e-3
    error('LPF_Analyze:ThdCycles', ...
        'THD transient must contain an integer number of cycles; found %.6g.', ...
        cycleCount);
end
lpfOutDiff_V = lpfOutDiff_V-mean(lpfOutDiff_V,'omitnan');
amplitude_Vpk = zeros(1,5);
for harmonic = 1:5
    angle = 2*pi*harmonic*fundamental_Hz*t_s;
    cosineCoefficient = 2/duration_s*trapz( ...
        t_s,lpfOutDiff_V.*cos(angle));
    sineCoefficient = 2/duration_s*trapz( ...
        t_s,lpfOutDiff_V.*sin(angle));
    amplitude_Vpk(harmonic) = hypot(cosineCoefficient,sineCoefficient);
end
if ~isfinite(amplitude_Vpk(1)) || amplitude_Vpk(1) <= 0
    error('LPF_Analyze:ThdFundamental', ...
        'THD fundamental amplitude must be finite and positive.');
end
result.amplitude_Vpk = amplitude_Vpk;
result.ratio = sqrt(sum(amplitude_Vpk(2:5).^2))/amplitude_Vpk(1);
result.percent = 100*result.ratio;
result.dB = 20*log10(result.ratio);
end

function value = integrateDensity(frequency,density,band)
[f,y] = boundedTrace(frequency,density,band);
value = sqrt(trapz(f,y.^2));
end

function [boundedFrequency,boundedValue] = boundedTrace(frequency,value,band)
if band(1) < frequency(1) || band(2) > frequency(end)
    error('LPF_Analyze:BandCoverage', ...
        'Requested band %.6g-%.6g Hz is outside the data range.',band(1),band(2));
end
inside = frequency > band(1) & frequency < band(2);
boundedFrequency = [band(1); frequency(inside); band(2)];
boundedValue = [interpLog(frequency,value,band(1)); ...
    value(inside); interpLog(frequency,value,band(2))];
end

function crossing_Hz = descendingCrossing(frequency,response_dB,level_dB,start_Hz)
startIndex = find(frequency >= start_Hz,1);
if isempty(startIndex)
    crossing_Hz = NaN;
    return;
end
left = response_dB(startIndex:end-1);
right = response_dB(startIndex+1:end);
relativeIndex = find(left > level_dB & right <= level_dB,1);
if isempty(relativeIndex)
    crossing_Hz = NaN;
    return;
end
index = startIndex+relativeIndex-1;
x1 = log10(frequency(index));
x2 = log10(frequency(index+1));
y1 = response_dB(index);
y2 = response_dB(index+1);
crossing_Hz = 10^(x1+(level_dB-y1)*(x2-x1)/(y2-y1));
end

function values = metricsToRaw(m,rows,temperature_C,targetGain_VV)
values = nan(size(rows,1),1);
for rowIndex = 1:size(rows,1)
    switch rows(rowIndex,1)
        case "AVDD", values(rowIndex) = m.vdd_V;
        case "Temperature", values(rowIndex) = temperature_C;
        case "LPF target gain", values(rowIndex) = targetGain_VV;
        case "FDC bias current", values(rowIndex) = m.fdcBias_A*1e6;
        case "CMFB bias current", values(rowIndex) = m.cmfbBias_A*1e6;
        case "Total current", values(rowIndex) = m.totalCurrent_A*1e3;
        case "Total power", values(rowIndex) = m.totalPower_W*1e3;
        case "Output CM error", values(rowIndex) = m.outputCmError_V*1e3;
        case "LPF input offset", values(rowIndex) = m.vos_V*1e3;
        case "Passband gain", values(rowIndex) = m.diff.gain10_VV;
        case "Passband gain error", values(rowIndex) = m.diff.gainError_pct;
        case "Loss @ 150 Hz", values(rowIndex) = m.diff.loss150_dB;
        case "LPF -1 dB frequency", values(rowIndex) = m.diff.frequency1dB_Hz;
        case "LPF -3 dB frequency", values(rowIndex) = m.diff.frequency3dB_Hz;
        case "Input range low", values(rowIndex) = m.vtc.inputNegative_V;
        case "Input range high", values(rowIndex) = m.vtc.inputPositive_V;
        case "Output range low", values(rowIndex) = m.vtc.outputNegative_V;
        case "Output range high", values(rowIndex) = m.vtc.outputPositive_V;
        case "CMRR @ 60 Hz", values(rowIndex) = m.rejection.cmrr_dB(1);
        case "CMRR @ 150 Hz", values(rowIndex) = m.rejection.cmrr_dB(2);
        case "PSRR+ @ 60 Hz", values(rowIndex) = m.rejection.psrrP_dB(1);
        case "PSRR+ @ 150 Hz", values(rowIndex) = m.rejection.psrrP_dB(2);
        case "PSRR- @ 60 Hz", values(rowIndex) = m.rejection.psrrN_dB(1);
        case "PSRR- @ 150 Hz", values(rowIndex) = m.rejection.psrrN_dB(2);
        case "Input-referred noise 0.05-150 Hz"
            values(rowIndex) = m.noise.inputRms_V*1e6;
        case "THD @ 60 Hz, 1.2 Vpp", values(rowIndex) = m.thd.percent;
    end
end
end

function relations = metricsToRelations(m,rows)
relations = strings(size(rows,1),1);
if m.vtc.negativeAtBoundary
    relations(rows(:,1) == "Input range low") = "≤";
    relations(rows(:,1) == "Output range low") = "≤";
end
if m.vtc.positiveAtBoundary
    relations(rows(:,1) == "Input range high") = "≥";
    relations(rows(:,1) == "Output range high") = "≥";
end
end

function result = buildFullPvtTable(rows,values,corners,processes,cases,vdd_V,temp_C,relations)
metricRows = find(rows(:,2) ~= "");
nRecords = numel(corners)*numel(metricRows);
cornerColumn = strings(nRecords,1);
processColumn = strings(nRecords,1);
caseColumn = strings(nRecords,1);
vddColumn = nan(nRecords,1);
tempColumn = nan(nRecords,1);
parameterColumn = strings(nRecords,1);
unitColumn = strings(nRecords,1);
valueColumn = strings(nRecords,1);
record = 0;
for cornerIndex = 1:numel(corners)
    range = record+(1:numel(metricRows));
    record = range(end);
    cornerColumn(range) = corners(cornerIndex);
    processColumn(range) = processes(cornerIndex);
    caseColumn(range) = cases(cornerIndex);
    vddColumn(range) = vdd_V(cornerIndex);
    tempColumn(range) = temp_C(cornerIndex);
    parameterColumn(range) = rows(metricRows,1);
    unitColumn(range) = rows(metricRows,2);
    for metricIndex = 1:numel(metricRows)
        rowIndex = metricRows(metricIndex);
        valueColumn(range(metricIndex)) = formatResult( ...
            values(rowIndex,cornerIndex),rows(rowIndex,2), ...
            relations(rowIndex,cornerIndex));
    end
end
result = table(cornerColumn,processColumn,caseColumn,vddColumn,tempColumn, ...
    parameterColumn,unitColumn,valueColumn, ...
    'VariableNames',{'Corner','Process','Environment','AVDD_V', ...
    'Temperature_C','Parameter','Unit','Value'});
end

function result = buildWorstCaseTable(rows,values,corners,relations)
definitions = [
    "FDC bias current",                       "FDC bias current",                       "maxspecmid"
    "CMFB bias current",                      "CMFB bias current",                      "maxspecmid"
    "Total current",                          "Total current",                          "max"
    "Total power",                            "Total power",                            "max"
    "Output CM error",                        "Output CM error",                        "maxspecmid"
    "LPF input offset",                       "LPF input offset",                       "maxspecmid"
    "Passband gain",                          "Passband gain",                          "linkedgain"
    "Passband gain error",                    "Passband gain error",                    "maxspecmid"
    "Loss @ 150 Hz",                          "Loss @ 150 Hz",                          "max"
    "LPF -1 dB frequency",                    "LPF -1 dB frequency",                    "min"
    "LPF -3 dB frequency",                    "LPF -3 dB frequency",                    "min"
    "Input range low",                        "Input range low",                        "max"
    "Input range high",                       "Input range high",                       "min"
    "Output range low",                       "Output range low",                       "max"
    "Output range high",                      "Output range high",                      "min"
    "CMRR @ 60 Hz",                           "CMRR @ 60 Hz",                           "min"
    "CMRR @ 150 Hz",                          "CMRR @ 150 Hz",                          "min"
    "PSRR+ @ 60 Hz",                          "PSRR+ @ 60 Hz",                          "min"
    "PSRR+ @ 150 Hz",                         "PSRR+ @ 150 Hz",                         "min"
    "PSRR- @ 60 Hz",                          "PSRR- @ 60 Hz",                          "min"
    "PSRR- @ 150 Hz",                         "PSRR- @ 150 Hz",                         "min"
    "Input-referred noise 0.05-150 Hz",       "Input-referred noise 0.05-150 Hz",       "max"
    "THD @ 60 Hz, 1.2 Vpp",                   "THD @ 60 Hz, 1.2 Vpp",                   "max"
];
n = size(definitions,1);
parameters = definitions(:,1);
units = strings(n,1);
specifications = strings(n,1);
selectedValues = nan(n,1);
selectedCorners = strings(n,1);
selectedRelations = strings(n,1);
for definitionIndex = 1:n
    sourceRow = parameterIndex(rows(:,1),definitions(definitionIndex,2));
    units(definitionIndex) = rows(sourceRow,2);
    candidates = values(sourceRow,:);
    mode = definitions(definitionIndex,3);
    if mode == "linkedgain"
        errorRow = parameterIndex(rows(:,1),"Passband gain error");
        selectionCandidates = values(errorRow,:);
        [~,selectedIndex] = max(abs(selectionCandidates));
    elseif any(~isfinite(candidates))
        selectedIndex = find(~isfinite(candidates),1);
    else
        switch mode
            case "min", [~,selectedIndex] = min(candidates);
            case "max", [~,selectedIndex] = max(candidates);
            case "maxspecmid"
                bounds = twoSidedBounds(definitions(definitionIndex,2));
                [~,selectedIndex] = max(abs(candidates-mean(bounds)));
            otherwise
                error('LPF_Analyze:WorstCaseMode','Unknown selection mode %s.',mode);
        end
    end
    selectedValues(definitionIndex) = candidates(selectedIndex);
    selectedCorners(definitionIndex) = corners(selectedIndex);
    selectedRelations(definitionIndex) = relations(sourceRow,selectedIndex);
    specifications(definitionIndex) = specText(definitions(definitionIndex,2));
end
formattedValues = strings(n,1);
for index = 1:n
    formattedValues(index) = formatResult( ...
        selectedValues(index),units(index),selectedRelations(index));
end
result = table(parameters,units,specifications,formattedValues,selectedCorners, ...
    'VariableNames',{'Parameter','Unit','Spec','Value','Corner'});
end

function bounds = twoSidedBounds(parameter)
switch string(parameter)
    case {"FDC bias current","CMFB bias current"}, bounds = [30 50];
    case "Output CM error", bounds = [-25 25];
    case "LPF input offset", bounds = [-6 6];
    case "Passband gain error", bounds = [-0.5 0.5];
    otherwise
        error('LPF_Analyze:MissingSpecBounds', ...
            'No two-sided bounds are defined for %s.',parameter);
end
end

function runMcSection(scriptDir,plotDir,reportDir,cfg)
modes = ["MM" "GL" "FULL"];
files = string({fullfile(scriptDir,'mm.Result_txt','mm.mc_summary.txt'), ...
    fullfile(scriptDir,'gl.Result_txt','gl.mc_summary.txt'), ...
    fullfile(scriptDir,'full.Result_txt','full.mc_summary.txt')});
missingFiles = files(~isfile(files));
if ~isempty(missingFiles)
    warning('LPF_Analyze:MissingMcSummaries', ...
        'MC reporting skipped. Missing source file(s):\n%s', ...
        strjoin(missingFiles,newline));
    return;
end

defs = mcDefinitions();
results = cell(numel(modes),1);
for modeIndex = 1:numel(modes)
    raw = readMcSummary(files(modeIndex));
    results{modeIndex} = summarizeMc(raw,defs,modes(modeIndex),cfg);
    printMcSummary(results{modeIndex});
    writetable(results{modeIndex}.table, ...
        fullfile(reportDir,modes(modeIndex)+"_MC_Summary.csv"));
end
runTable = table(modes',cellfun(@(r)r.requested,results), ...
    cellfun(@(r)r.valid,results),cellfun(@(r)r.failed,results), ...
    cellfun(@(r)r.overallYield,results), ...
    'VariableNames',{'Mode','RequestedRuns','ValidRuns','FailedRuns', ...
    'OverallYield_pct'});
writetable(runTable,fullfile(reportDir,'MC_Run_Summary.csv'));
plotMcHistograms(results,defs,plotDir);
plotMcCmrrHistograms(results,defs,plotDir);
end

function defs = mcDefinitions
defs.names = ["FDC bias current" "CMFB bias current" "Total current" ...
    "Total power" "Output CM error" "LPF input offset" ...
    "Passband gain" "Passband gain error" ...
    "LPF -1 dB frequency" "LPF -3 dB frequency" ...
    "CMRR @ 60 Hz" "CMRR @ 150 Hz"];
defs.units = ["uA" "uA" "mA" "mW" "mV" "mV" ...
    "V/V" "%" "Hz" "Hz" "dB" "dB"];
defs.specs = specStrings(defs.names);
defs.required = strlength(defs.specs) > 0;
defs.plotParameters = ["LPF -1 dB frequency" "LPF input offset"];
defs.plotFiles = ["Fig_MC_01_LPF_1dB_Frequency_Histogram.png" ...
    "Fig_MC_02_Input_Offset_Histogram.png"];
end

function raw = readMcSummary(filePath)
raw = readmatrix(filePath,'FileType','text');
raw = raw(any(isfinite(raw),2),:);
raw = raw(:,any(isfinite(raw),1));
if ~ismember(size(raw,2),[14 15])
    error('LPF_Analyze:McColumns', ...
        '%s must contain 14 or 15 numeric columns; found %d.', ...
        filePath,size(raw,2));
end
end

function result = summarizeMc(raw,defs,mode,cfg)
if size(raw,2) == 14
    fdc = raw(:,2); cmfb = raw(:,3); current = raw(:,4); power = raw(:,5);
    cmError = raw(:,6); offset = raw(:,7); gain10 = raw(:,8);
    f1 = raw(:,11); f3 = raw(:,12);
    cmrr60 = raw(:,13); cmrr150 = raw(:,14);
else
    fdc = raw(:,2); cmfb = raw(:,3); current = raw(:,4); power = raw(:,5);
    cmError = raw(:,6); offset = raw(:,7); gain10 = raw(:,8);
    f1 = raw(:,12); f3 = raw(:,13);
    cmrr60 = raw(:,14); cmrr150 = raw(:,15);
end
values = [fdc*1e6 cmfb*1e6 current*1e3 power*1e3 cmError*1e3 ...
    offset*1e3 gain10 100*(gain10-cfg.targetGain_VV)/cfg.targetGain_VV ...
    f1 f3 cmrr60 cmrr150];
validMask = all(isfinite(values),2);
count = numel(defs.names);
stats = nan(count,7);
yield = nan(count,1);
pass = false(size(values));
for parameterIndexValue = 1:count
    validValues = values(validMask,parameterIndexValue);
    if isempty(validValues), continue; end
    mu = mean(validValues);
    sigma = std(validValues,0);
    stats(parameterIndexValue,:) = [min(validValues) mu-3*sigma ...
        mu-sigma mu mu+sigma mu+3*sigma max(validValues)];
    if defs.required(parameterIndexValue)
        for sampleIndex = find(validMask)'
            pass(sampleIndex,parameterIndexValue) = specPass( ...
                defs.names(parameterIndexValue),values(sampleIndex,parameterIndexValue));
        end
        yield(parameterIndexValue) = 100*nnz( ...
            pass(validMask,parameterIndexValue))/nnz(validMask);
    end
end
if any(validMask)
    overallPass = all(pass(validMask,defs.required),2);
    overallYield = 100*nnz(overallPass)/nnz(validMask);
else
    overallYield = NaN;
end
result.mode = mode;
result.values = values;
result.validMask = validMask;
result.stats = stats;
result.requested = cfg.mcRequestedRuns;
result.valid = nnz(validMask);
result.failed = max(0,result.requested-result.valid);
result.overallYield = overallYield;
yieldText = strings(count,1);
for parameterIndexValue = 1:count
    if defs.required(parameterIndexValue)
        yieldText(parameterIndexValue) = ...
            sprintf('%.2f',yield(parameterIndexValue));
    end
end
result.table = table(defs.names',defs.units',defs.specs',stats(:,1), ...
    stats(:,2),stats(:,3),stats(:,4),stats(:,5),stats(:,6),stats(:,7),yieldText, ...
    'VariableNames',{'Parameter','Unit','Spec','Min','MeanMinus3Sigma', ...
    'MeanMinusSigma','Mean','MeanPlusSigma','MeanPlus3Sigma','Max','Yield_pct'});
end

function printMcSummary(result)
fprintf('\n%s MONTE CARLO SUMMARY\n',result.mode);
fprintf('Requested: %d  Valid: %d  Failed: %d  Overall yield: %.2f%%\n', ...
    result.requested,result.valid,result.failed,result.overallYield);
t = result.table;
parameterWidth = max(40,max(strlength(t.Parameter))+2);
fprintf('%-*s %-8s %-12s %10s %10s %10s %10s %10s %10s %10s %9s\n', ...
    parameterWidth,'Parameter','Unit','Spec','Min','μ-3σ','μ-σ','Mean', ...
    'μ+σ','μ+3σ','Max','Yield');
for index = 1:height(t)
    fprintf('%-*s %-8s %-12s %10s %10s %10s %10s %10s %10s %10s %9s\n', ...
        parameterWidth,t.Parameter(index),t.Unit(index),t.Spec(index), ...
        formatFixed(t.Min(index)),formatFixed(t.MeanMinus3Sigma(index)), ...
        formatFixed(t.MeanMinusSigma(index)),formatFixed(t.Mean(index)), ...
        formatFixed(t.MeanPlusSigma(index)),formatFixed(t.MeanPlus3Sigma(index)), ...
        formatFixed(t.Max(index)),t.Yield_pct(index));
end
end

function plotMcHistograms(results,defs,plotDir)
for plotIndex = 1:numel(defs.plotParameters)
    metricIndex = parameterIndex(defs.names,defs.plotParameters(plotIndex));
    valueSets = cellfun(@(r)r.values(r.validMask,metricIndex), ...
        results,'UniformOutput',false);
    allValues = vertcat(valueSets{:});
    if isempty(allValues), continue; end
    specBounds = mcSpecBounds(defs.names(metricIndex));
    [lower,upper,fullResult] = mcDisplayRange( ...
        allValues,results,metricIndex);
    edges = linspace(lower,upper,21);
    fig = figure;
    hold on;
    colors = lines(numel(results));
    for resultIndex = 1:numel(results)
        result = results{resultIndex};
        sample = result.values(result.validMask,metricIndex);
        sample = sample(isfinite(sample) & sample >= lower & sample <= upper);
        if isempty(sample), continue; end
        probabilityPct = 100*histcounts(sample,edges,'Normalization','probability');
        stairs(edges,[probabilityPct 0],'LineWidth',1.5, ...
            'Color',colors(resultIndex,:),'DisplayName',result.mode);
    end
    addMcSpecLines(specBounds,lower,upper);
    addFullStatMarkers(fullResult,metricIndex);
    xlim([lower upper]);
    ylabel('Samples (%)');
    titlePrefix = "LPF ";
    if startsWith(defs.names(metricIndex),"LPF ")
        titlePrefix = "";
    end
    stylePlot(defs.names(metricIndex)+" ("+defs.units(metricIndex)+")", ...
        titlePrefix+defs.names(metricIndex)+" Distribution - MM / GL / FULL");
    legend('Location','northeast');
    savePlot(fig,plotDir,defs.plotFiles(plotIndex));
end
end

function plotMcCmrrHistograms(results,defs,plotDir)
parameters = ["CMRR @ 60 Hz" "CMRR @ 150 Hz"];
fig = figure;
layout = tiledlayout(fig,2,1);
for plotIndex = 1:numel(parameters)
    metricIndex = parameterIndex(defs.names,parameters(plotIndex));
    valueSets = cellfun(@(r)r.values(r.validMask,metricIndex), ...
        results,'UniformOutput',false);
    allValues = vertcat(valueSets{:});
    if isempty(allValues), continue; end
    specBounds = mcSpecBounds(parameters(plotIndex));
    [lower,upper,fullResult] = mcDisplayRange( ...
        allValues,results,metricIndex);
    edges = linspace(lower,upper,21);
    nexttile(layout); hold on;
    colors = lines(numel(results));
    for resultIndex = 1:numel(results)
        result = results{resultIndex};
        sample = result.values(result.validMask,metricIndex);
        sample = sample(isfinite(sample) & sample >= lower & sample <= upper);
        if isempty(sample), continue; end
        probabilityPct = 100*histcounts(sample,edges,'Normalization','probability');
        stairs(edges,[probabilityPct 0],'LineWidth',1.5, ...
            'Color',colors(resultIndex,:),'DisplayName',result.mode);
    end
    addMcSpecLines(specBounds,lower,upper);
    addFullStatMarkers(fullResult,metricIndex);
    xlim([lower upper]);
    ylabel('Samples (%)');
    stylePlot(parameters(plotIndex)+" (dB)", ...
        parameters(plotIndex)+" Distribution - MM / GL / FULL");
    legend('Location','northeast');
end
savePlot(fig,plotDir,'Fig_MC_03_CMRR_Histogram.png');
end

function bounds = mcSpecBounds(parameter)
switch string(parameter)
    case "LPF -1 dB frequency", bounds = [150 Inf];
    case "LPF input offset", bounds = [-6 6];
    case "CMRR @ 60 Hz", bounds = [80 Inf];
    otherwise, bounds = [-Inf Inf];
end
end

function [lower,upper,fullResult] = mcDisplayRange(values,results,metricIndex)
% Center every MC x-axis on the FULL mean.
fullIndex = find(cellfun(@(r)strcmpi(string(r.mode),"FULL"),results),1);
if isempty(fullIndex)
    fullIndex = numel(results);
end
fullResult = results{fullIndex};
center = fullResult.stats(metricIndex,4);
if ~isfinite(center)
    fullValues = fullResult.values(:,metricIndex);
    center = mean(fullValues(isfinite(fullValues)),'omitnan');
end
if ~isfinite(center)
    center = mean(values,'omitnan');
end

limits = nan(numel(results),2);
for resultIndex = 1:numel(results)
    mu = results{resultIndex}.stats(metricIndex,4);
    sigma = abs(results{resultIndex}.stats(metricIndex,5)-mu);
    if isfinite(mu) && isfinite(sigma)
        limits(resultIndex,:) = [mu-4*sigma mu+4*sigma];
    end
end
finiteLimits = limits(isfinite(limits));
if isempty(finiteLimits)
    halfRange = max(abs(values-center),[],'omitnan');
else
    halfRange = max(abs(finiteLimits-center),[],'omitnan');
end
if ~isfinite(halfRange) || halfRange <= 0
    halfRange = max(abs(center)*0.05,1);
end
halfRange = 1.05*halfRange;
lower = center-halfRange;
upper = center+halfRange;
end

function addMcSpecLines(bounds,lower,upper)
for value = bounds(:)'
    if isfinite(value) && value >= lower && value <= upper
        xline(value,'--','HandleVisibility','off');
    end
end
end

function addFullStatMarkers(fullResult,metricIndex)
markers = fullResult.stats(metricIndex,2:6);
labels = ["-3σ" "-σ" "μ" "+σ" "+3σ"];
for markerIndex = 1:numel(markers)
    addCursorLine(markers(markerIndex),labels(markerIndex));
end
end

