function plotSelectorTransient(scriptDir,plotDir)
filePath = fullfile(scriptDir,'nom.Result_txt','nom.sel_tran_nom.txt');
data = readNumericFile(filePath,5);
if any(diff(data(:,1)) <= 0)
    error('LPF_Analyze:SelectorTime', ...
        'Selector transient time must be strictly increasing: %s',filePath);
end
time_ms = data(:,1)*1e3;
sel_V = data(:,2);
internal_mV = data(:,3)*1e3;
external_mV = data(:,4)*1e3;
output_mV = data(:,5)*1e3;
switchTime_ms = selectorSwitchTime(time_ms,sel_V,filePath);
fig = figure;
layout = tiledlayout(fig,3,1);
controlAxes = nexttile(layout);
plot(time_ms,sel_V,'LineWidth',1.5);
hold on;
addSelectorSwitchGuide(switchTime_ms,true);
ylim([-0.15 max(sel_V)+0.15]);
ylabel('SEL (V)');
stylePlot('','(a) SEL Control');
signalAxes = nexttile(layout);
yyaxis left;
internalLine = plot(time_ms,internal_mV,'LineWidth',1.5, ...
    'DisplayName','INT input differential');
hold on;
internalLimit_mV = max(abs(internal_mV),[],'omitnan');
ylim(1.05*[-internalLimit_mV internalLimit_mV]);
ylabel('INT input differential (mV)');
yyaxis right;
externalLine = plot(time_ms,external_mV,'--','LineWidth',1.5, ...
    'DisplayName','EXT input differential');
externalLimit_mV = max(abs(external_mV),[],'omitnan');
ylim(1.05*[-externalLimit_mV externalLimit_mV]);
ylabel('EXT input differential (mV)');
addSelectorSwitchGuide(switchTime_ms,false);
legend([internalLine externalLine],'Location','northeast');
stylePlot('','(b) Available INT and EXT Input Signals');
outputAxes = nexttile(layout);
plot(time_ms,output_mV,'LineWidth',2.0, ...
    'DisplayName','OUT differential');
addSelectorSwitchGuide(switchTime_ms,false);
outputLimit_mV = max(abs([internal_mV; external_mV; output_mV]), ...
    [],'omitnan');
ylim(1.05*[-outputLimit_mV outputLimit_mV]);
ylabel('Output differential (mV)');
stylePlot('Time (ms)','(c) Selected Output');
linkaxes([controlAxes signalAxes outputAxes],'x');
xlim([time_ms(1) time_ms(end)]);
sgtitle('SEL LPF / EXT Functional Check - NOM');
savePlot(fig,plotDir,'NOM.LPF_SEL_functional_check.png');
end

function switchTime_ms = selectorSwitchTime(time_ms,sel_V,filePath)
lowLevel_V = min(sel_V,[],'omitnan');
highLevel_V = max(sel_V,[],'omitnan');
threshold_V = 0.5*(lowLevel_V+highLevel_V);
switchIndex = find(sel_V >= threshold_V,1,'first');
if ~isfinite(lowLevel_V) || ~isfinite(highLevel_V) || ...
        highLevel_V <= lowLevel_V || isempty(switchIndex)
    error('LPF_Analyze:SelectorSwitch', ...
        'Selector control does not contain a low-to-high switch: %s',filePath);
end
switchTime_ms = time_ms(switchIndex);
end

function addSelectorSwitchGuide(switchTime_ms,showRegionLabels)
xline(switchTime_ms,'--','HandleVisibility','off');
if showRegionLabels
    text(0.25,0.90,'LPF Selected','Units','normalized', ...
        'HorizontalAlignment','center','VerticalAlignment','top', ...
        'HandleVisibility','off');
    text(0.75,0.90,'EXT Selected','Units','normalized', ...
        'HorizontalAlignment','center','VerticalAlignment','top', ...
        'HandleVisibility','off');
end
end

function printSummaryTable(rows,specifications,columns,values)
parameterWidth = max(42,max(strlength(rows(:,1)))+2);
fprintf('%-*s %-8s %-14s',parameterWidth,'Parameter','Unit','Spec');
for index = 1:numel(columns), fprintf(' %13s',columns(index)); end
fprintf('\n%s\n',repmat('-',1,parameterWidth+24+14*numel(columns)));
for rowIndex = 1:size(rows,1)
    if rows(rowIndex,1) == "" && rows(rowIndex,2) == ""
        fprintf('\n');
    elseif rows(rowIndex,2) == ""
        fprintf('%-*s\n',parameterWidth,upper(rows(rowIndex,1)));
    else
        fprintf('%-*s %-8s %-14s',parameterWidth,rows(rowIndex,1), ...
            rows(rowIndex,2),specifications(rowIndex));
        for columnIndex = 1:numel(columns)
            fprintf(' %13s',values(rowIndex,columnIndex));
        end
        fprintf('\n');
    end
end
end

function printWorstCaseTable(tableValue)
parameterWidth = max(42,max(strlength(tableValue.Parameter))+2);
fprintf('%-*s %-8s %-14s %13s %-10s\n',parameterWidth, ...
    'Parameter','Unit','Spec','Value','Corner');
fprintf('%s\n',repmat('-',1,parameterWidth+49));
for index = 1:height(tableValue)
    fprintf('%-*s %-8s %-14s %13s %-10s\n',parameterWidth, ...
        tableValue.Parameter(index),tableValue.Unit(index), ...
        tableValue.Spec(index),tableValue.Value(index),tableValue.Corner(index));
end
end

function formatted = formatReportValues(rows,values,relations)
formatted = strings(size(values));
for rowIndex = 1:size(values,1)
    if rows(rowIndex,2) == "", continue; end
    for columnIndex = 1:size(values,2)
        formatted(rowIndex,columnIndex) = formatResult( ...
            values(rowIndex,columnIndex),rows(rowIndex,2), ...
            relations(rowIndex,columnIndex));
    end
end
end

function textValue = formatResult(value,unit,relation)
textValue = formatOne(value,unit);
if strlength(relation) > 0
    textValue = relation+textValue;
end
end

function textValue = formatOne(value,unit)
if isnan(value)
    textValue = "NaN";
elseif isinf(value)
    textValue = string(sprintf('%+g',value));
elseif unit == "dB" || unit == "%"
    if value ~= 0 && (abs(value) < 1e-3 || abs(value) > 999)
        textValue = string(sprintf('%.3e',value));
    else
        textValue = string(sprintf('%.3f',value));
    end
else
    textValue = string(sprintf('%.3f',value));
end
end

function textValue = formatFixed(value)
if ~isfinite(value), textValue = "N/A";
elseif value ~= 0 && (abs(value) < 1e-3 || abs(value) >= 1e4)
    textValue = string(sprintf('%.3e',value));
else, textValue = string(sprintf('%.3f',value));
end
end

function index = parameterIndex(parameters,parameter)
index = find(parameters == parameter,1);
if isempty(index)
    error('LPF_Analyze:MissingParameter', ...
        'Required parameter is not defined: %s',parameter);
end
end

function value = readScalar(filePath)
data = readNumericFile(filePath,1);
value = data(find(isfinite(data(:,1)),1,'last'),1);
end

function data = readNumericFile(filePath,minimumColumns)
if ~isfile(filePath)
    error('LPF_Analyze:MissingFile','Missing required file: %s',filePath);
end
data = readmatrix(filePath,'FileType','text');
data = data(any(isfinite(data),2),:);
data = data(:,any(isfinite(data),1));
if isempty(data)
    error('LPF_Analyze:EmptyFile','No numeric data found in %s.',filePath);
end
if size(data,2) ~= minimumColumns
    error('LPF_Analyze:ColumnCount', ...
        '%s has %d columns; expected %d.', ...
        filePath,size(data,2),minimumColumns);
end
if any(~isfinite(data),'all')
    error('LPF_Analyze:NonfiniteData', ...
        '%s contains nonfinite required data.',filePath);
end
end

function validateFrequency(frequency,label)
if any(~isfinite(frequency)) || any(frequency <= 0) || any(diff(frequency) <= 0)
    error('LPF_Analyze:FrequencyAxis', ...
        '%s frequency must be finite, positive, and strictly increasing.',label);
end
end

function result = interpLog(frequency,value,queryFrequency)
if any(queryFrequency < frequency(1) | queryFrequency > frequency(end))
    error('LPF_Analyze:InterpolationRange', ...
        'Requested frequency is outside the available data range.');
end
result = interp1(log10(frequency),value,log10(queryFrequency),'linear');
end

function textValue = frequencyText(frequency_Hz)
if ~isfinite(frequency_Hz)
    textValue = "NaN";
elseif frequency_Hz >= 1e3
    textValue = string(sprintf('%.4g kHz',frequency_Hz/1e3));
else
    textValue = string(sprintf('%.4g Hz',frequency_Hz));
end
end

function addMetricBox(lines)
text(0.98,0.94,strjoin(lines,newline),'Units','normalized', ...
    'BackgroundColor','w','Color','k','Margin',4, ...
    'VerticalAlignment','top','HorizontalAlignment','right', ...
    'HandleVisibility','off');
end

function addCursor(xValue,yValue,labelText)
if ~isfinite(xValue) || ~isfinite(yValue)
    return;
end
xline(xValue,':','HandleVisibility','off');
plot(xValue,yValue,'o','MarkerFaceColor','r','MarkerEdgeColor','r', ...
    'MarkerSize',6,'HandleVisibility','off');
text(xValue,yValue," "+string(labelText),'BackgroundColor','w', ...
    'Color','k','Margin',2,'VerticalAlignment','bottom', ...
    'HorizontalAlignment','left','Clipping','on','HandleVisibility','off');
end

function addCursorLine(xValue,labelText)
if ~isfinite(xValue), return; end
xline(xValue,':'," "+string(labelText),'HandleVisibility','off', ...
    'LabelVerticalAlignment','middle','LabelHorizontalAlignment','left');
end

function stylePlot(xLabelText,titleText)
grid on;
if strlength(string(xLabelText)) > 0, xlabel(xLabelText); end
if strlength(string(titleText)) > 0, title(titleText); end
end

function savePlot(fig,plotDir,fileName)
drawnow;
fig.PaperUnits = 'inches';
fig.PaperPosition = [0 0 10 4];
fig.PaperSize = [10 4];
print(fig,fullfile(plotDir,fileName),'-dpng','-r250');
end
